export function publicProjection(v){if(Array.isArray(v))return v.map(publicProjection);if(v&&typeof v==='object')return Object.fromEntries(Object.entries(v).filter(([k,x])=>{if(privateKeys.has(k)&&typeof x==='string'&&/^[A-Za-z]:[\\/]/u.test(x))return false;check(!commercialKeys.has(k),'Commercial provider data remains private');return true;}).map(([k,x])=>[k,publicProjection(x)]));check(typeof v!=='string'||!/(?:^|\s)[A-Za-z]:[\\/]/u.test(v),'Unexpected private path');return v;}
