export function validateActual(a,k){check(canonicalHash(a)===k.actual,'Accepted actual signature changed');check(a.category===k.category&&a.language==='ja'&&(a.nativeName??a.visibleNativeTitle??a.nativeTitle)&&a.setMark==='R','Actual Japanese category/title/R required');check(a.printedCollectorNumber===null&&a.canonicalAliasIsUnprintedIndex===true,'Catalogue alias is not printed collector');if(k.category==='Pokemon'){check(Number.isInteger(a.printedNationalDex)&&a.printedNationalDex>0&&a.printedNumberIsNationalDex===true,'Actual printed NationalDex required');check(Number.isInteger(a.hp)&&a.hp>0&&a.stage&&Number.isInteger(a.retreat)&&a.retreat>=0&&Array.isArray(a.attacks)&&a.attacks.length>0,'Full Pokemon body required');}else{check(['Trainer','Energy'].includes(k.category)&&a.printedHeader===(k.category==='Trainer'?'TRAINER':'ENERGY'),'Exact nonPokemon header required');check(a.printedNationalDex===null&&a.printedNumberIsNationalDex===false&&a.hp===null&&a.stage===null&&a.retreat===null&&a.attacks.length===0&&a.abilities.length===0,'NonPokemon cannot borrow Pokemon fields');check(a.nativeRules?.length>0,'Full actual native nonPokemon rules required');if(k.category==='Energy')check(a.printedSubtitle==='特殊エネルギーカード'&&a.energyProvides,'Actual Special Energy body required');}}
