export function projectQueueControls(raw){const k=knownSource(raw.printingId);validateActual(raw.acceptedActualPixelSignature,k);const p=k.category==='Pokemon';return{pixel_observations:{whole_original_inspected:true,full_frame_visible:true,name_number_and_symbol_readable:p,name_and_set_symbol_readable:true,full_native_body_verified:true,full_native_nonpokemon_body_verified:!p,exact_art_reference_verified:true},identity_controls:{canonical_alias:k.alias,canonical_alias_is_internal_only:true,canonical_alias_is_not_printed_national_dex:true,printed_collector_number:null,printed_national_dex:raw.acceptedActualPixelSignature.printedNationalDex,pokemon_identity_asserted:p},source_qa:{actual_japanese_full_front_verified:true,actual_japanese_pokemon_front_verified:p,actual_japanese_unnumbered_trainer_front_verified:k.category==='Trainer',actual_japanese_unnumbered_energy_front_verified:k.category==='Energy',printed_number_and_national_dex_absent_verified:!p,original_sha256:k.original,actual_pixel_signature_sha256:k.actual}};}
